 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max((v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    segments = []
    # Any two 1 markers on a 45-degree diagonal define a segment to connect.
    for i, (r0, c0) in enumerate(ones):
        for r1, c1 in ones[i + 1:]:
            if abs(r1-r0) == abs(c1-c0) and r1 != r0:
                sr = 1 if r1 > r0 else -1
                sc = 1 if (r1-r0)*(c1-c0) > 0 else -1
                n = abs(r1-r0)
                cells = [(r0 + sr*k, c0 + sc*k) for k in range(n+1)]
                segments.append((cells, sr, sc))
                for r, c in cells:
                    if grid[r][c] == bg or grid[r][c] == 1:
                        out[r][c] = 1

    # A 6 on a connecting 1 segment emits a perpendicular diagonal to the grid edge.
    for cells, sr, sc in segments:
        cellset = set(cells)
        for r6, c6 in sixes:
            if (r6, c6) not in cellset:
                continue
            pr, pc = -sc, sr
            for sign in (-1, 1):
                r, c = r6, c6
                while 0 <= r < h and 0 <= c < w:
                    if grid[r][c] == bg or grid[r][c] == 6:
                        out[r][c] = 6
                    r += sign*pr
                    c += sign*pc
    return out
